ode":"216000","name":"ประกันสังคมค้างจ่าย","group":"liability","section":"หนี้สินหมุนเวียน","normal":"credit","active":true},{"code":"217000","name":"กองทุนสำรองเลี้ยงชีพค้างจ่าย","group":"liability","section":"หนี้สินหมุนเวียน","normal":"credit","active":true},{"code":"218000","name":"รายการหักพนักงานรอนำส่ง","group":"liability","section":"หนี้สินหมุนเวียน","normal":"credit","active":true},{"code":"219000","name":"เงินเดือนสุทธิค้างจ่าย","group":"liability","section":"หนี้สินหมุนเวียน","normal":"credit","active":true},{"code":"220000","name":"เงินกู้ยืมระยะยาว","group":"liability","section":"เงินกู้ยืม","normal":"credit","active":true},{"code":"310000","name":"ทุนเจ้าของ","group":"equity","section":"ทุน","normal":"credit","active":true},{"code":"320000","name":"กำไรสะสม","group":"equity","section":"กำไรสะสม","normal":"credit","active":true},{"code":"330000","name":"ถอนใช้ส่วนตัวเจ้าของ","group":"equity","section":"ถอนใช้ส่วนตัว","normal":"debit","active":true},{"code":"390000","name":"ยอดยกมาตั้งต้นรอตรวจสอบ","group":"equity","section":"ยอดยกมา","normal":"credit","active":true},{"code":"410000","name":"รายได้ค่าบริการ","group":"income","section":"รายได้จากการดำเนินงาน","normal":"credit","active":true},{"code":"420000","name":"รายได้ขายสินค้า","group":"income","section":"รายได้จากการดำเนินงาน","normal":"credit","active":true},{"code":"421000","name":"รายได้ค่าขนส่ง","group":"income","section":"รายได้จากการดำเนินงาน","normal":"credit","active":true},{"code":"430000","name":"ส่วนลดจ่าย / ลดรายได้","group":"income","section":"ส่วนลด","normal":"debit","active":true},{"code":"490000","name":"รายได้อื่น","group":"income","section":"รายได้อื่น","normal":"credit","active":true},{"code":"510000","name":"ต้นทุนสินค้า / อะไหล่และวัสดุ","group":"expense","section":"ต้นทุนขายและบริการ","normal":"debit","active":true},{"code":"511000","name":"ค่าจ้างช่าง / ผู้รับเหมา","group":"expense","section":"ต้นทุนขายและบริการ","normal":"debit","active":true},{"code":"519000","name":"ส่วนลดร